#include <iostream>
#include <vector>
#include <algorithm>
int main() {
    std::vector<int> a = {1,2,3,4,5};
    std::vector<int> b(a.size());
    std::transform(a.begin(), a.end(), b.begin(), [](int x){ return x * x; });
    for (int x : b) std::cout << x << ' ';
    std::cout << '\n';
    std::transform(a.begin(), a.end(), a.begin(), [](int x){ return x + 1; });
    for (int x : a) std::cout << x << ' ';
    std::cout << '\n';
}
